output_schema:
Working code examples for all endpoints in multiple languages
{
  "examples_by_endpoint": [
    {
      "endpoint_id": "string - Reference to endpoint",
      "endpoint_summary": "string - Quick reference",
      "curl_example": {
        "command": "string - Complete curl command",
        "explanation": "string - What the command does"
      },
      "code_examples": [
        {
          "language": "string",
          "code": "string - Complete working code",
          "dependencies": ["string - Required packages"],
          "setup_notes": "string | null - Any setup required"
        }
      ],
      "sample_request": {
        "headers": "object",
        "body": "object | null"
      },
      "sample_response": {
        "status": "number",
        "headers": "object",
        "body": "object"
      }
    }
  ],
  "authentication_examples": {
    "setup": "string - How to configure auth",
    "examples_by_language": [
      {
        "language": "string",
        "code": "string - Auth setup code"
      }
    ]
  },
  "common_patterns": [
    {
      "pattern_name": "string - e.g., 'pagination', 'error_handling'",
      "description": "string",
      "code_examples": [
        {
          "language": "string",
          "code": "string"
        }
      ]
    }
  ],
  "sdk_examples": {
    "available": "boolean",
    "installation": "string | null",
    "examples": [
      {
        "endpoint_id": "string",
        "code": "string"
      }
    ]
  }
}
